/*
 *  prog50_binary_heap.c
 *
 *  Behaviour (as observed from the original binary):
 *
 *      - If the program is started without any command line arguments
 *        (i.e. argc < 2) it prints the single line
 *
 *              NOOP
 *
 *        and exits.
 *
 *      - Otherwise each argument argv[i] (i = 1 … argc‑1) is interpreted as a
 *        command.  The program maintains a *min‑heap* of signed 64‑bit integers
 *        with a fixed capacity of 16 elements (size 0 … 16).
 *
 *        * Insert command:  I<number>
 *              The argument must start with the character 'I' followed
 *              immediately by a decimal integer (no leading spaces, no
 *              trailing characters).  If the format is wrong the program
 *              prints
 *
 *                      ERR
 *
 *              If the heap is already full (16 elements) it prints
 *
 *                      FULL
 *
 *              Otherwise the integer is inserted into the heap, the heap
 *              property is restored (sift‑up) and the program prints
 *
 *                      INS %ld\n          (the inserted value)
 *
 *        * Extract‑minimum command:  X
 *              The argument must be exactly the single character 'X'.
 *              If it is anything else the program prints
 *
 *                      ERR
 *
 *              If the heap is empty it prints
 *
 *                      EMPTY
 *
 *              Otherwise the smallest element is removed, the heap property
 *              is restored (sift‑down) and the program prints
 *
 *                      MIN %ld\n          (the extracted value)
 *
 *        * Any other command also results in the line
 *
 *              ERR
 *
 *        The program processes the arguments in order and terminates with
 *        return code 0.
 *
 *  The implementation below reproduces exactly that observable behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>

#define HEAP_CAPACITY 16

static int64_t heap[HEAP_CAPACITY];
static int      size = 0;          /* current number of elements in the heap */

/* --------------------------------------------------------------- */
/* Helper functions for the binary min‑heap                         */
/* --------------------------------------------------------------- */

static void heap_swap(int i, int j)
{
    int64_t tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

/* Restore heap property after inserting at position idx (sift‑up). */
static void heap_sift_up(int idx)
{
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap[parent] <= heap[idx])
            break;
        heap_swap(parent, idx);
        idx = parent;
    }
}

/* Restore heap property after removing the root (sift‑down). */
static void heap_sift_down(int idx)
{
    while (1) {
        int left  = idx * 2 + 1;
        int right = idx * 2 + 2;
        int smallest = idx;

        if (left < size && heap[left] < heap[smallest])
            smallest = left;
        if (right < size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest == idx)
            break;

        heap_swap(idx, smallest);
        idx = smallest;
    }
}

/* --------------------------------------------------------------- */
/* Main program                                                    */
/* --------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* No arguments -> NOOP */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int arg_idx = 1; arg_idx < argc; ++arg_idx) {
        const char *cmd = argv[arg_idx];

        /* --------------------------------------------------- */
        /* INSERT command:  I<number>                           */
        /* --------------------------------------------------- */
        if (cmd[0] == 'I') {
            const char *num_str = cmd + 1;
            char *endptr = NULL;
            long long value = strtoll(num_str, &endptr, 10);

            /* Invalid number (no digits) or extra characters? */
            if (endptr == num_str || *endptr != '\0') {
                puts("ERR");
                continue;
            }

            if (size >= HEAP_CAPACITY) {
                puts("FULL");
                continue;
            }

            heap[size] = value;
            heap_sift_up(size);
            ++size;

            printf("INS %lld\n", value);
            continue;
        }

        /* --------------------------------------------------- */
        /* EXTRACT‑MIN command:  X                               */
        /* --------------------------------------------------- */
        if (strcmp(cmd, "X") == 0) {
            if (size == 0) {
                puts("EMPTY");
                continue;
            }

            int64_t min_val = heap[0];
            heap[0] = heap[size - 1];
            --size;
            heap_sift_down(0);

            printf("MIN %lld\n", min_val);
            continue;
        }

        /* --------------------------------------------------- */
        /* Anything else is an error                             */
        /* --------------------------------------------------- */
        puts("ERR");
    }

    return 0;
}
